function showWords(){pause();screen('words');if(window.LinguTabs){window.LinguTabs.words();return;}var box=$('wordItems');box.textContent='';var meanings={'Every day, Noah goes to the library.':'Noah her gün kütüphaneye gider.','He always carries that old notebook.':'O eski defteri hep yanında taşır.','What does he do in there?':'Orada ne yapıyor?','I draw pictures.':'Resim çizerim.','Because I’m shy.':'Çünkü utangacım.','Do you want to join us?':'Bize katılmak ister misin?','Yes, I’d love to!':'Evet, çok isterim!','I wake up when the sun comes through.':'Güneş doğduğunda uyanırım.','I grab my bag, got things to do.':'Çantamı alırım, yapacak işlerim var.','I play, she plays.':'Ben oynarım, o oynar.','I do, you do, we do, they do.':'Ben yaparım, sen yaparsın, biz yaparız, onlar yapar.','He goes, she goes, now you know.':'O gider, o gider; artık biliyorsun.','He doesn’t run, she doesn’t hide.':'O koşmaz, o saklanmaz.','Do you know? Yeah, I do!':'Biliyor musun? Evet, biliyorum!','Does she know? Yes, she does too!':'O biliyor mu? Evet, o da biliyor!'};['stories','songs'].forEach(function(k){var title=document.createElement('h2');title.textContent=modules[k].data.title;box.appendChild(title);modules[k].data.expressions.forEach(function(expression){var button=document.createElement('button');button.className='word-card';var en=document.createElement('b');en.lang='en';en.textContent=expression;var tr=document.createElement('span');tr.className='hidden';tr.textContent=meanings[expression]||'Bu ifadeyi içerikteki bağlamıyla keşfet.';button.setAttribute('aria-expanded','false');button.appendChild(en);button.appendChild(tr);button.onclick=function(){var open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));tr.classList.toggle('hidden',!open);};box.appendChild(button);});});}
