function showCatalog(kind){if(cmsActive){save();pause();modules={stories:{...cmsDefaults.stories},songs:{...cmsDefaults.songs}};cmsActive=false;}pause();category=kind;$('catalog').setAttribute('data-kind',kind);screen('catalog');$('catalogTitle').textContent={stories:'Hikâyeler',songs:'Şarkılar',games:'Oyunlar'}[kind];$('catalogDescription').textContent=kind==='songs'?'Ritme katıl, sözleri takip et ve İngilizceyi keşfet.':kind==='games'?'İçeriğini seç; izlediğin video veya dinlediğin şarkıyla oyna.':'Bir hikâye seç, yeni bir dünyaya katıl.';var box=$('catalogItems');box.textContent='';if(kind==='stories'||kind==='songs'){var m=modules[kind],card=document.createElement('button');card.className='content-card';card.setAttribute('data-content',kind);var img=document.createElement('div');img.className='content-image';if(m.data.id===m.defaultId)img.style.backgroundImage="url('"+m.poster+"')";var copy=document.createElement('span');copy.className='content-card-copy';var tag=document.createElement('small');tag.textContent=(kind==='songs'?'ŞARKI · ':'HİKÂYE · ')+window.LinguAudience.display(m.data);var title=document.createElement('b');title.lang='en';title.textContent=m.data.title;var meta=document.createElement('span'),progress=moduleStats(kind);meta.textContent=progress.xp?progress.xp+' XP · '+progress.finished+' etkinlik tamamlandı':kind==='songs'?'Sözlü video · 4 etkinlik · Ayrı ilerleme':'İzle · Etkinliğini seç · Öğren';copy.appendChild(tag);copy.appendChild(title);copy.appendChild(meta);card.appendChild(img);card.appendChild(copy);card.onclick=function(){selectModule(kind);intro();};box.appendChild(card);return;}['stories','songs'].forEach(function(k){var m=modules[k];activities.forEach(function(a){var g=group(m.data,a.id);if(!g.questions.length)return;var b=document.createElement('button');b.className='catalog-game';b.setAttribute('data-module',k);b.setAttribute('data-game',a.id);var h=document.createElement('b');h.textContent=k==='songs'?{quiz:'Şarkı Testi',who:'Kelime Avı',order:'Sözleri Sırala',grammar:'Dil Bilgisi Oyunları'}[a.id]:a.name;var t=document.createElement('span');t.textContent='Önce içeriği tamamla, ardından etkinliğine katıl.';var name=document.createElement('small');name.lang='en';name.textContent=m.data.title;b.appendChild(h);b.appendChild(t);b.appendChild(name);b.onclick=function(){selectModule(k);if(watched){enter(false);chooseActivity(a.id);}else intro();};box.appendChild(b);});});}
function introBase(){pause();mode='watch';demo=false;preview=false;active=story;loadProgress();screen('landing');$('storyTitle').textContent=story.title;$('storyLevel').textContent=window.LinguAudience.display(story);$('storyDescription').textContent=story.description;document.querySelector('.hero-image').style.backgroundImage=poster()?"url('"+poster()+"')":'none';$('startBtn').firstChild.nodeValue=watched?'Etkinliklerini Seç ':isSong()?'Şarkıyı Dinle ':'Hikâyeyi İzle ';$('resumeNote').textContent=watched?'Hikâyeyi tamamladın. Etkinliklerine istediğin sırayla devam edebilirsin.':gate.frontier>1?'Kaldığın yer hatırlandı. Hikâyeye oradan devam edebilirsin.':'Deneme etkinlikleri puanlarına eklenmez. Gerçek yolculuk hikâyeyi izleyince başlar.';var box=$('activityPreview');box.textContent='';activities.forEach(function(a){a=activityInfo(a);var g=group(story,a.id);if(!g.questions.length)return;var d=document.createElement('div'),name=document.createElement('b'),info=document.createElement('span');name.textContent=a.name;info.textContent=a.description;d.appendChild(name);d.appendChild(info);box.appendChild(d);});}
function enter(autoplay){demo=false;preview=false;active=story;loadProgress();if(expectedKey&&expectedKey!==videoKey){resetAll();$('watchNote').textContent='Hikâyenin videosu henüz hazır değilse öğretmeninden yardım isteyebilirsin.';}currentActivity=null;$('demoBadge').classList.add('hidden');$('videoPlaceholder').classList.add('hidden');screen('experience');renderExperience();if(!watched&&autoplay!==false&&video.currentSrc){if(gate.frontier>1&&isFinite(video.duration))video.currentTime=Math.min(gate.frontier,video.duration);safePlay();}}
function startDemo(id,bank){pause();demo=true;preview=!!bank;watched=false;demoStory=bank?normalize(bank):story;demoBuckets=blankBuckets(demoStory);active=demoStory;session=E.fresh(demoStory);currentActivity=null;gate=new E.WatchGate(0);$('demoBadge').classList.remove('hidden');$('demoBadge').textContent=preview?'ÖĞRETMEN ÖNİZLEMESİ · Puanlar kaydedilmez':'ÖNİZLEME · Puanların kaydedilmez';$('watchNote').textContent='Etkinlikleri burada deneyebilirsin. Deneme puanların gerçek ilerlemene eklenmez.';$('videoPlaceholder').classList.toggle('hidden',!!video.currentSrc&&!video.error);screen('experience');renderExperience();if(id){var q=E.find(demoStory,id),a=activities.filter(function(v){return v.types.indexOf(q.type)>=0;})[0];chooseActivity(a.id,true);var at=session.queue.map(function(v){return v.id;}).indexOf(id);if(at>0)session.queue.unshift(session.queue.splice(at,1)[0]);renderQuestionScreen();}}
function hidePanels(){['lockedPanel','activityPanel','instructionPanel','questionPanel','finishPanel'].forEach(function(k){$(k).classList.add('hidden');});}
function renderExperienceBase(target){updateStats();$('experienceTitle').textContent=runStory().title;$('scenePill').textContent=runStory().title.toUpperCase();hidePanels();if(!demo&&!watched){mode='watch';$('phaseLabel').textContent='ÖNCE HİKÂYEYİ İZLE';$('lockedPanel').classList.remove('hidden');$('resumeWatchBtn').classList.toggle('hidden',gate.frontier<1);return;}if(target==='question'&&currentActivity){renderQuestionScreen();return;}mode='activities';$('phaseLabel').textContent='HİKÂYEYİ KEŞFETTİN · ŞİMDİ SEN SEÇ';$('activityPanel').classList.remove('hidden');renderActivities();}
function renderActivitiesBase(){var box=$('activityCards');box.textContent='';activities.forEach(function(a,i){a=activityInfo(a);var g=group(runStory(),a.id),st=runBuckets()[a.id];if(!g.questions.length)return;var m=E.metrics(g,st),b=document.createElement('button');b.className='activity-card'+(m.completion===100?' completed':'');b.setAttribute('data-activity',a.id);var number=document.createElement('span');number.className='activity-number';number.textContent=('0'+(i+1)).slice(-2);var text=document.createElement('span');var title=document.createElement('b');title.textContent=a.name;var sub=document.createElement('small');sub.textContent=m.learned+' / '+m.total+' soru · '+m.xp+' XP';var status=document.createElement('span');status.className='activity-status';status.textContent=m.completion===100?'Yeniden Oyna':Object.keys(st.attempts).length?'Devam Et':'Başla';text.appendChild(title);text.appendChild(sub);b.appendChild(number);b.appendChild(text);b.appendChild(status);b.onclick=function(){chooseActivity(a.id);};box.appendChild(b);});}
function chooseActivity(id,skip){if(!demo&&!watched){msg('Etkinlikler için önce hikâyenin tamamını izle.');renderExperience();return;}pause();var a=activities.filter(function(v){return v.id===id;})[0];if(!a)return;a=activityInfo(a);active=group(runStory(),id);if(!active.questions.length)return;currentActivity=id;session=runBuckets()[id];activityReplay=!session.queue.length;if(activityReplay)session=E.fresh(active);window.dispatchEvent(new CustomEvent('lingucat:activity-start',{detail:{demo:demo,module:currentModule,activityId:id}}));hidePanels();mode='instruction';$('phaseLabel').textContent=a.name.toLocaleUpperCase('tr-TR');$('instructionTitle').textContent=a.name;$('instructionText').textContent=a.instruction;var m=E.metrics(active,session);$('instructionProgress').textContent=activityReplay?'Bu etkinliği yeniden yapabilirsin. Kazandığın XP ve ilerleme korunur.':m.learned?m.learned+' / '+m.total+' soru öğrendin. Kaldığın yer hazır.':m.total+' soru seni bekliyor. Acele etmeden ilerle.';$('beginActivity').textContent=activityReplay?'Yeniden Başlayalım →':Object.keys(session.attempts).length?'Kaldığım Yerden Devam Et →':'Başlayalım →';updateStats();save();renderQuestionScreen();}
function renderQuestionScreen(){if(!demo&&!watched){renderExperience();return;}if(!session.queue.length){finish();return;}hidePanels();$('questionPanel').classList.remove('hidden');mode='mission';renderQuestion();}
function current(){return session&&session.queue.length?E.find(active,session.queue[0].id):null;}
function reflection(){renderQuestionMedia({});var target=E.find(active,session.queue[0].id);reflectionQuestion=runStory().questions.filter(function(q){return q.id!==target.id&&q.type!=='order';})[0]||null;reflectionAnswered=false;selectedAnswer=null;$('questionType').textContent='Kısa Bir Hatırlatma';$('questionCount').textContent='Bu arada başka bir soruyla hatırlayalım.';$('attemptLabel').textContent='HATIRLATMA ARASI · Puan verilmez';$('sceneLabel').textContent='İlgili sahneye dön.';$('answers').textContent='';$('feedback').className='feedback';$('feedback').textContent='Bu hatırlatma sorusu etkinlik puanını değiştirmez.';$('queueNote').textContent='Sonra zorlandığın soruya yeniden döneceksin.';$('nextBtn').disabled=!!reflectionQuestion;$('nextBtn').textContent=reflectionQuestion?'Cevabı Kontrol Et':'Sonraki Soru →';if(reflectionQuestion){$('questionPrompt').lang='en';$('questionPrompt').textContent=reflectionQuestion.prompt;$('questionHint').textContent='Hikâyeden başka bir ayrıntıyı hatırla. Bir seçenek işaretledikten sonra devam edebilirsin.';reflectionQuestion.options.forEach(function(label,i){var b=document.createElement('button');b.className='answer-card';b.textContent=label;b.onclick=function(){if(reflectionAnswered)return;selectedAnswer=i;Array.prototype.forEach.call($('answers').querySelectorAll('button'),function(x,j){x.classList.toggle('selected',j===i);x.setAttribute('aria-pressed',String(j===i));});$('nextBtn').disabled=false;$('nextBtn').textContent='Cevabı Kontrol Et';};$('answers').appendChild(b);});}else{$('questionPrompt').lang='tr';$('questionPrompt').textContent='Hikâyeye bir kez daha dön.';$('questionHint').textContent='Bu hikâyede tek soru var. İlgili sahneyi izle ve ipuçlarını düşün; sonra yeniden dene.';}}
function renderQuestionMedia(q){var box=$('questionMedia');if(!box){box=document.createElement('div');box.id='questionMedia';$('questionPrompt').insertAdjacentElement('afterend',box);}box.querySelectorAll('audio').forEach(function(a){a.pause();});box.textContent='';if(q.image){var im=document.createElement('img');im.src=q.image;im.alt='Sorunun görseli';box.appendChild(im);}if(q.audio){var audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=q.audio;audio.setAttribute('aria-label','Sorunun sesini dinle');box.appendChild(audio);}}
function renderQuestionBase(){if(session.pause){reflection();return;}var q=current(),entry=session.queue[0],m=E.metrics(active,session);selectedAnswer=null;order=q.options.map(function(_,i){return i;});if(q.type==='order'&&JSON.stringify(order)===JSON.stringify(q.answer))order.push(order.shift());$('questionPrompt').lang='en';$('questionType').textContent=types[q.type];$('questionCount').textContent=Math.min(m.total,m.learned+(session.answered&&session.result.correct?0:1))+' / '+m.total+' soru';$('missionFill').style.width=m.completion+'%';$('missionFill').parentNode.setAttribute('aria-valuenow',m.completion);$('attemptLabel').textContent=entry.bridge?'HATIRLATMA ARASI · Puan verilmez':((session.attempts[q.id]||0)+(session.answered?0:1))+'. deneme';$('questionPrompt').textContent=q.prompt;renderQuestionMedia(q);$('questionHint').textContent=q.type==='vocabulary'?'İfadenin şarkıdaki anlamını seç.':q.type==='speaker'?'Cümleyi söyleyen karakteri seç.':q.type==='order'?'Olayları oklarla sırala. Hazır olduğunda kontrol et.':q.type==='boolean'?'İfadenin doğru mu yanlış mı olduğuna karar ver.':q.type==='grammar'?'Cümleye en uygun doğru seçeneği bul.':'Hikâyeye göre en doğru seçeneği işaretle.';$('sceneLabel').textContent='İpucu için ilgili bölüme dön.';$('queueNote').textContent=activityReplay?'Tekrar etkinliği · Kazanılmış XP ve ilerleme korunur.':entry.bridge?'Bu soru, zorlandığın sorudan önce kısa bir hatırlatma.':session.round>1?session.round+'. tur · Her denemede biraz daha öğren.':'İlk doğru cevap: 100 XP · İkinci deneme: 50 XP · Sonraki denemeler: 20 XP';$('nextBtn').disabled=!session.answered;$('nextBtn').textContent=session.answered?'Sonraki Soru →':'Cevabı Kontrol Et';$('feedback').className='feedback';$('feedback').textContent=entry.bridge?'Kısa bir hatırlatma: burada puan verilmez.':'Acele etme. İhtiyaç duyarsan sahneyi tekrar izle.';$('questionPanel').classList.remove('question-enter');void $('questionPanel').offsetWidth;$('questionPanel').classList.add('question-enter');drawAnswers();if(session.answered)feedback();}
function drawAnswers(){var q=current(),box=$('answers');box.textContent='';if(q.type==='order'){order.forEach(function(n,i){var row=document.createElement('div');row.className='order-row';var pos=document.createElement('b');pos.textContent=('0'+(i+1)).slice(-2);var label=document.createElement('span');label.textContent=q.options[n];row.appendChild(pos);row.appendChild(label);[-1,1].forEach(function(dir){var b=document.createElement('button');b.textContent=dir===-1?'↑':'↓';b.lang='tr';b.setAttribute('aria-label',(i+1)+'. olayı '+(dir===-1?'yukarı':'aşağı')+' taşı');b.disabled=session.answered||i+dir<0||i+dir>=order.length;b.onclick=function(){var v=order[i];order[i]=order[i+dir];order[i+dir]=v;selectedAnswer=order.slice();drawAnswers();$('nextBtn').disabled=false;};row.appendChild(b);});box.appendChild(row);});}else q.options.forEach(function(label,i){var b=document.createElement('button');b.className='answer-card';b.disabled=session.answered;b.setAttribute('data-answer',i);var letter=document.createElement('span');letter.className='letter';letter.textContent=String.fromCharCode(65+i);var txt=document.createElement('span');txt.textContent=label;b.appendChild(letter);b.appendChild(txt);b.setAttribute('aria-pressed',String(selectedAnswer===i));if(selectedAnswer===i)b.classList.add('selected');b.onclick=function(){selectedAnswer=i;Array.prototype.forEach.call(box.querySelectorAll('.answer-card'),function(c,j){c.classList.toggle('selected',j===i);c.setAttribute('aria-pressed',String(j===i));});$('nextBtn').disabled=false;};box.appendChild(b);});}
function submit(value){if(!demo&&!watched)return;var result=E.answer(active,session,value);if(!result)return;window.dispatchEvent(new CustomEvent('lingucat:answer',{detail:{kind:'activity',module:currentModule,contentId:active.id,activityId:currentActivity,questionId:session.queue[0].id,value:value,demo:demo,review:activityReplay}}));if(activityReplay){session.xp-=result.xp;result.xp=0;}tone(result.correct,result.xp);drawAnswers();feedback();updateStats();save();}
function feedbackBase(){var q=current(),r=session.result;if(!r)return;$('feedback').className='feedback '+(r.correct?'good':'bad');$('feedback').textContent=r.correct?(r.bridge?'Güzel bir hatırlatma! Bu soruda puan verilmez. ':(activityReplay?'Harika! Doğru cevap. ':'Harika! '+r.xp+' XP kazandın. '))+q.feedback:'Bu kez olmadı. Soruyla daha sonra tekrar karşılaşacaksın. İpucu için “Sahneyi Tekrar İzle” düğmesine basabilirsin.';$('nextBtn').disabled=false;$('nextBtn').textContent='Sonraki Soru →';if(!r.correct){var correctText=q.type==='order'?q.answer.map(function(i){return q.options[i];}).join(' → '):q.options[q.answer];$('feedback').textContent='Doğru cevap: '+correctText+'. Bu soruyu tekrar deneyeceksin.';}if(q.type!=='order'){var buttons=$('answers').querySelectorAll('button');buttons[q.answer].classList.add('correct');if(!r.correct&&selectedAnswer!==null)buttons[selectedAnswer].classList.add('wrong');}}
function advance(){if(session.pause){session.pause=false;save();renderQuestionScreen();return;}if(!E.next(active,session))return;pause();save();renderQuestionScreen();if(current())$('questionPrompt').focus();}
function finish(review){pause();hidePanels();mode='finish';$('finishPanel').classList.remove('hidden');var a=activities.filter(function(v){return v.id===currentActivity;})[0],m=E.metrics(active,session);a=activityInfo(a);$('phaseLabel').textContent='BİR ETKİNLİK DAHA TAMAMLANDI';$('resultTitle').textContent=a.name+' tamamlandı!';$('resultXp').textContent=m.xp+' XP';var box=$('resultStats');box.textContent='';[['%'+m.first,'İlk deneme başarısı'],[m.learned+' / '+m.total,'Öğrenilen soru'],[String(m.repeated),'Tekrar edilen soru']].forEach(function(pair){var d=document.createElement('div'),n=document.createElement('strong'),t=document.createElement('span');n.textContent=pair[0];t.textContent=pair[1];d.appendChild(n);d.appendChild(t);box.appendChild(d);});var list=$('expressions');list.textContent='';active.expressions.forEach(function(e){var li=document.createElement('li');li.textContent=e;list.appendChild(li);});var repeated=active.questions.filter(function(q){return (session.attempts[q.id]||0)>1;});$('reviewSummary').textContent=repeated.length?'Bu etkinlikte '+repeated.length+' soruya yeniden döndün. Hepsini öğrenerek tamamladın.':'Bu etkinlikte bütün soruları ilk denemede doğru cevapladın.';updateStats();save();window.dispatchEvent(new CustomEvent('lingucat:activity-complete',{detail:{review:!!review||activityReplay,demo:demo,xp:m.xp,title:a.name,module:currentModule,activityId:currentActivity,contentId:runStory().id,revision:E.revision(runStory()),metrics:m}}));}
function replayScene(q){if(!q)return;if(!video.currentSrc||video.error){msg('Hikâyenin videosu henüz hazır değil. Öğretmeninden videoyu eklemesini isteyebilirsin.');return;}if(!isFinite(video.duration)){msg('Video hazırlanıyor. Birkaç saniye sonra tekrar dene.');return;}if(q.scene.start>=video.duration||q.scene.end>video.duration+.15){msg('Bu sahne şu anda açılamıyor. Etkinliğe devam edebilir veya öğretmeninden yardım isteyebilirsin.');return;}video.pause();mode='replay';replayStart=q.scene.start;replayEnd=Math.min(q.scene.end,video.duration);video.currentTime=replayStart;$('scenePill').textContent='SAHNE TEKRARI';$('watchNote').textContent='İlgili sahne bitince video duracak. Cevabın ve ilerlemen yerinde kalır.';safePlay();}
function metadataBase(){if(!isFinite(video.duration)||!video.duration)return;$('videoStatus').textContent='Hikâyen oynatılmaya hazır.';if(Math.abs(video.duration-runStory().videoDuration)>1){$('watchNote').textContent='Bazı sahneleri tekrar açmak için öğretmenin küçük bir düzenleme yapması gerekebilir. Hikâyeyi izlemeye devam edebilirsin.';}if(gate.frontier>video.duration)gate.frontier=0;updateStats();}
function rewatch(){if(!video.currentSrc||video.error){msg('Bu hikâyenin videosu henüz hazır değil. Öğretmeninden yardım isteyebilirsin.');return;}if(!watched&&!demo){mode='watch';}else mode='rewatch';replayEnd=null;video.currentTime=0;safePlay();}
video.addEventListener('loadedmetadata',metadata);video.addEventListener('error',function(){$('videoStatus').textContent='Bu hikâyenin videosu henüz hazır değil.';$('watchNote').textContent='Başka bir hikâye seçebilir, etkinlikleri deneyebilir veya öğretmeninden yardım isteyebilirsin.';if(demo)$('videoPlaceholder').classList.remove('hidden');});
video.addEventListener('timeupdate',function(){if(mode==='replay'){if(replayEnd!==null&&video.currentTime>=replayEnd-.04){video.pause();video.currentTime=replayEnd;replayEnd=null;mode=currentActivity?'mission':'activities';$('scenePill').textContent='SAHNE TEKRARI TAMAMLANDI';}return;}if(mode==='watch'&&!demo&&!watched){gate.sample(video.currentTime,Date.now(),!video.paused||video.ended,video.playbackRate);updateStats();if(Date.now()-lastSave>2000){lastSave=Date.now();save();}}});
video.addEventListener('seeking',function(){if(mode==='watch'&&!watched&&!demo){var allowed=gate.seek(video.currentTime);if(Math.abs(allowed-video.currentTime)>.1){// A positive first-frame offset avoids a Chrome seek-to-zero decoder stall.
video.currentTime=Math.max(.001,allowed);msg('Önce hikâyeyi tamamla. İzlediğin bölümlere istediğin zaman dönebilirsin.');}}else if(mode==='replay'&&replayEnd!==null&&(video.currentTime<replayStart||video.currentTime>replayEnd))video.currentTime=replayStart;});video.addEventListener('seeked',function(){gate.endSeek();});video.addEventListener('playing',function(){if(mode==='watch')gate.sample(video.currentTime,Date.now(),false,video.playbackRate);});
video.addEventListener('pause',function(){if(mode==='watch'){gate.sample(video.currentTime,Date.now(),true,video.playbackRate);gate.last=null;updateStats();save();}});video.addEventListener('ended',function(){if(mode==='watch'&&!demo&&!watched){gate.sample(video.currentTime,Date.now(),true,video.playbackRate);if(gate.complete(video.duration)){watched=true;save();$('watchNote').textContent='Hikâyeyi tamamladın! Şimdi istediğin etkinliği seçebilirsin.';window.dispatchEvent(new CustomEvent('lingucat:content-unlocked'));if(!window.LinguFX)tone(true);setTimeout(function(){renderExperience();},450);}else msg('Hikâyenin tamamı henüz izlenmedi. Kaldığın yerden devam edebilirsin.');}});
